**1. Reading YouTube videos frame-by-frame to summarize content.**
Core code:

```
import subprocess
import yt_dlp
import base64
import shutil

def analyze_youtube_frames_ffmpeg(url, interval=5, max_frames=20, res=(640, 360)):
    if not shutil.which("ffmpeg"):
        return {"error": "ffmpeg missing"}

    with yt_dlp.YoutubeDL({'format': 'best[ext=mp4]', 'quiet': True}) as ydl:
        stream_url = ydl.extract_info(url, download=False)['url']

    cmd = [
        'ffmpeg', '-i', stream_url, 
        '-vf', f'fps=1/{interval},scale={res[0]}:{res[1]}', 
        '-f', 'image2pipe', '-vcodec', 'mjpeg', '-q:v', '2', '-'
    ]

    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, bufsize=10**7)
    frames, buf = [], b""

    while True:
        chunk = proc.stdout.read(4096)
        if not chunk and proc.poll() is not None:
            break
        buf += chunk

        while True:
            start, end = buf.find(b'\xff\xd8'), buf.find(b'\xff\xd9')
            if start != -1 and end != -1 and end > start:
                if len(frames) < max_frames:
                    frames.append({
                        "timestamp": (len(frames) + 1) * interval,
                        "image_base64": base64.b64encode(buf[start:end+2]).decode()
                    })
                else:
                    proc.kill()
                    return frames
                buf = buf[end+2:]
            else:
                break
    return frames
```

**2. Querying Wikipedia to count edits containing a specific tag on a specific page within a specific time interval.**
Core code:

```
import requests

def count_wikipedia_edits(page, tag, start, end, lang="en"):
    api = f"https://{lang}.wikipedia.org/w/api.php"
    params = {
        "action": "query", "format": "json", "prop": "revisions", "titles": page,
        "rvprop": "timestamp|user|comment|size", "rvstart": start, "rvend": end,
        "rvlimit": "max", "rvdir": "newer"
    }

    matches = []
    while True:
        data = requests.get(api, params=params).json()
        pages = data.get("query", {}).get("pages", {})

        for pid, pdata in pages.items():
            if pid == "-1": return {"error": "Page not found"}
            for rev in pdata.get("revisions", []):
                if tag.lower() in rev.get("comment", "").lower():
                    matches.append(rev)

        if "continue" in data:
            params["rvcontinue"] = data["continue"]["rvcontinue"]
        else:
            break

    return {
        "page": page, "tag": tag, 
        "total_matches": len(matches), 
        "samples": matches[:5]
    }
```

These tools are superior because they encapsulate complex logic into a single, reliable function call. This reduces the cognitive load on the agent and prevents repetitive coding errors, leading to the observed efficiency gains (15% token reduction) and higher accuracy.
